fn broadcast_arrays(a: Vec<i8>, b: Vec<i8>) -> (Vec<i8>, Vec<i8>) {
    let m = a.len();
    let n = b.len();
    let out_len = m.max(n);

    // Helper to broadcast a vector of length 1 to length out_len,
    // or clone if already length out_len.
    fn broadcast(vec: &[i8], len: usize) -> Vec<i8> {
        if vec.len() == 1 {
            vec.repeat(len)
        } else {
            vec.to_vec()
        }
    }

    // Since problem states inputs are compatible:
    // Either lengths equal or one length is 1.
    // So we just broadcast each vector individually.
    let out_a = broadcast(&a, out_len);
    let out_b = broadcast(&b, out_len);

    (out_a, out_b)
}